blocks.text:
字段名 | 字段描述 | 字段样例
host | 域名 | sso.example.com
res_sens_map | 响应敏感及敏感值去重数 | {'手机':40,'身份证':10,'银行卡':34}

{
  "APIs": [
    {
      "Name": "vip_ip_sens",
      "Sql": "SELECT host, uniqMapMerge(res_sens_mp_state) res_sens_map FROM ( SELECT host, uniqMapState(mapFilter((k, v) -> (k IN ['手机', '银行卡', '身份证', '身份证(未成年)', '地址(详细)']), mapFromArrays(res_sens_k, res_sens_v))) res_sens_mp_state FROM access WHERE org <> 'no_res' AND (ts >= toDateTime('{{ .start_ts }}', 'Asia/Shanghai') AND ts < toDateTime('{{ .end_ts }}', 'Asia/Shanghai')) AND length(res_sens_k) > 0 AND ip = '{{ .ip }}' AND If('{{ .host }}' AS inputHost = '<no value>', 1, host = inputHost) AND If('{{ .user }}' AS inputUser = '<no value>', 1, uid = inputUser) GROUP BY host ) GROUP BY host HAVING length(res_sens_map) > 0 FORMAT JSON SETTINGS max_execution_time=180",
      "Template": "{ \"code\": {{.Status}}, \"data\": {{.Data}} }"
    }
  ]
}
